with valid as (select *, concat_ws(',', category, product_name) as category_product_name_key, length(product_name) as product_name_length from products where stock_qty >= 126), enriched as (select id, product_name, price, cost, tags, supplier_id, category_product_name_key, product_name_length, sum(product_name_length) over w_recent as running_sum_product_name_length, count(product_name_length) over w_recent as running_count_product_name_length, avg(product_name_length) over w_recent as running_avg_product_name_length from valid window w_recent as (partition by brand, category order by price asc, id asc rows between unbounded preceding and current row)), scored as (select id, product_name, cost, category_product_name_key, product_name_length, running_sum_product_name_length, running_count_product_name_length, running_avg_product_name_length, avg(cost) over (partition by supplier_id order by product_name_length asc, id asc rows between 3 preceding and current row) as last4_avg_cost, max(cost) over (partition by supplier_id order by product_name_length asc, id asc rows between 3 preceding and current row) as last4_max_cost, min(cost) over (partition by supplier_id order by product_name_length asc, id asc rows between 3 preceding and current row) as last4_min_cost from enriched), metrics as (select id, cost, category_product_name_key, running_sum_product_name_length, last4_avg_cost, last4_max_cost, max(product_name_length) over (order by cost asc, id asc rows between 6 preceding and current row) as last7_max_product_name_length, avg(product_name_length) over (order by cost asc, id asc rows between 6 preceding and current row) as last7_avg_product_name_length, min(product_name_length) over (order by cost asc, id asc rows between 6 preceding and current row) as last7_min_product_name_length, sum(product_name_length) over (order by cost asc, id asc rows between 6 preceding and current row) as last7_sum_product_name_length from scored), daily as (select case when last4_max_cost >= 720 then 'LARGE' else 'SMALL' end as last4_max_cost_tier, case when last4_avg_cost >= 680 then 'PREMIUM' else 'STANDARD' end as last4_avg_cost_tier, percentile_approx(running_sum_product_name_length, 0.9) as running_sum_product_name_length_p90, count(distinct id) as distinct_ids, count(*) as num_rows from metrics group by rollup (case when last4_max_cost >= 720 then 'LARGE' else 'SMALL' end, case when last4_avg_cost >= 680 then 'PREMIUM' else 'STANDARD' end)) select last4_max_cost_tier, last4_avg_cost_tier, running_sum_product_name_length_p90, distinct_ids, num_rows from daily order by last4_max_cost_tier asc nulls last;
